flowchart TD
  start["Início: Isolar a oração com forma nominal"] --> dec_teste_isso{"Teste 1: Aceita substituição por 'ISSO / DISSO / A ISSO'?"}
  dec_teste_isso -- "Sim" --> res_substantiva["Oração Subordinada Substantiva Reduzida"]
  dec_teste_isso -- "Não" --> dec_teste_adj{"Teste 2: Qualifica substantivo e aceita 'QUE + verbo flexionado'?"}
  dec_teste_adj -- "Sim" --> dec_virgula{"A oração está isolada por vírgulas?"}
  dec_virgula -- "Sim (com vírgulas)" --> res_adj_explicativa["Oração Subordinada Adjetiva Explicativa Reduzida"]
  dec_virgula -- "Não (sem vírgulas)" --> res_adj_restritiva["Oração Subordinada Adjetiva Restritiva Reduzida"]
  dec_teste_adj -- "Não" --> dec_teste_adv{"Teste 3: Expressa circunstância em relação à oração principal?"}
  dec_teste_adv -- "Sim" --> res_adverbial["Oração Subordinada Adverbial Reduzida (6CS + FTP)"]
  dec_teste_adv -- "Não" --> res_inclassificavel["Reavaliar oração: Coordenada Reduzida ou Estrutura Absoluta"]
